use super::*;
use crate::DomainError;
use proptest::prelude::*;

// Real inputs from git 2.43.0, generated by `testdata/patch.sh` (`sh patch.sh testdata`) in a
// temporary repo with `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1` and fixed dates, with
// `git -c core.quotePath=false diff` and the arguments of [`DIFF_ARGS`].

/// `d` (worktree → index), input of staging: two nearby hunks with several changes
/// (`near.txt`), end of file without a newline in every combination, CRLF, non-UTF-8 content, non-
/// UTF-8 name, file deleted from the worktree, `git add -N` file (new), mode changed with lines.
const WORKTREE: &[u8] = include_bytes!("testdata/patch-worktree.bin");
/// `d --cached` (HEAD → index), input of unstaging: two hunks with nearby changes, trailing
/// newline added, both without a newline, CRLF, new file, deleted file, rename with
/// changes to a name with a space, name with a tab (quoted).
const INDEX: &[u8] = include_bytes!("testdata/patch-index.bin");
/// The script that generates the files: it must use the same arguments as [`DIFF_ARGS`].
const SCRIPT: &str = include_str!("testdata/patch.sh");

// The cases to reject need the parser's test files (`testdata/diff.sh`).
const FILE: &[u8] = include_bytes!("testdata/diff-file.bin");
const SUBMODULE: &[u8] = include_bytes!("testdata/diff-submodule.bin");
const CONFLICT: &[u8] = include_bytes!("testdata/diff-conflict.bin");

use LineRef::{New, Old};
use PatchDirection::{Stage, Unstage};

fn file(input: &[u8], path: &[u8]) -> FileDiff {
    let diff = parse_diff(input).expect("valid real output");
    let mut found = diff
        .files
        .into_iter()
        .filter(|f| f.new_path.as_bytes() == path);
    let f = found.next().expect("file present");
    assert!(found.next().is_none(), "only one file with this path");
    f
}

fn patch(f: &FileDiff, lines: &[LineRef], direction: PatchDirection) -> FileDiff {
    let p = build_patch(f, lines, direction)
        .expect("patch built")
        .expect("non-empty patch");
    // The patch is a valid diff: it is read back identical.
    let bytes = p.to_patch();
    assert_eq!(
        parse_diff(&bytes).expect("readable patch").files,
        std::slice::from_ref(&p)
    );
    p
}

/// The patch as text for snapshots, without losing bytes: a real tab is `→`, a `\r` is `␍`,
/// a non-UTF-8 or control byte is `⟨xx⟩` in hexadecimal.
fn render(p: &FileDiff) -> String {
    let mut out = String::new();
    for chunk in p.to_patch().utf8_chunks() {
        for c in chunk.valid().chars() {
            match c {
                '\t' => out.push('→'),
                '\r' => out.push('␍'),
                '\n' => out.push('\n'),
                c if c.is_control() => out.push_str(&format!("⟨{:02x}⟩", c as u32)),
                c => out.push(c),
            }
        }
        for b in chunk.invalid() {
            out.push_str(&format!("⟨{b:02x}⟩"));
        }
    }
    out
}

fn snapshot(name: &str, input: &[u8], path: &[u8], lines: &[LineRef], dir: PatchDirection) {
    let f = file(input, path);
    insta::assert_snapshot!(name, render(&patch(&f, lines, dir)));
}

#[test]
fn the_script_uses_the_parser_arguments() {
    let args = DIFF_ARGS.join(" ");
    assert!(SCRIPT.contains(&format!("git -c core.quotePath=false diff {args} \"$@\"")));
}

// --- Stage (worktree diff) -------------------------------------------------------------

#[test]
fn stage_near_hunks() {
    // Only the replacement of line 1: the old line 2 stays as context, line 2 of the
    // worktree (unselected addition) disappears, like the changes further on.
    snapshot(
        "stage_near_partial",
        WORKTREE,
        b"near.txt",
        &[Old(1), New(1)],
        Stage,
    );
    // One line per group, in different groups of the same hunk.
    snapshot(
        "stage_near_sparse",
        WORKTREE,
        b"near.txt",
        &[Old(4), New(9), Old(16)],
        Stage,
    );
}

#[test]
fn stage_full_selection_equals_the_diff() {
    let diff = parse_diff(WORKTREE).unwrap();
    for f in diff.files.iter().filter(|f| f.change == Change::Modified) {
        let p = patch(f, &f.line_refs(), Stage);
        assert_eq!(p.hunks, f.hunks, "{}", f.path());
    }
}

#[test]
fn stage_end_of_file_without_newline() {
    // `-b⏎\ No newline`, `+b`, `+c\ No newline`: only `+c` gives the same patch as the whole,
    // because `b` gets the newline.
    snapshot("stage_tail_only_c", WORKTREE, b"tail.txt", &[New(3)], Stage);
    // Only `+b` (with newline): the old `b` stays, gets the newline, and `b` is added.
    snapshot("stage_tail_only_b", WORKTREE, b"tail.txt", &[New(2)], Stage);
    // Only `-b`: the file ends with `a` and its newline.
    snapshot(
        "stage_tail_only_removed",
        WORKTREE,
        b"tail.txt",
        &[Old(2)],
        Stage,
    );
    // Only the added line without a newline: the old one stays as context with its newline.
    snapshot(
        "stage_removes_newline_only_added",
        WORKTREE,
        b"removes-newline.txt",
        &[New(2)],
        Stage,
    );
    // Line added before the last line without a newline (context): the marker stays there.
    snapshot(
        "stage_both_without",
        WORKTREE,
        b"both-without.txt",
        &[New(1)],
        Stage,
    );
}

#[test]
fn stage_exact_bytes() {
    snapshot("stage_crlf", WORKTREE, b"crlf.txt", &[New(4)], Stage);
    snapshot("stage_latin1", WORKTREE, b"latin1.txt", &[New(3)], Stage);
    snapshot(
        "stage_name_non_utf8",
        WORKTREE,
        b"name\xff.txt",
        &[New(4)],
        Stage,
    );

    let p = patch(&file(WORKTREE, b"crlf.txt"), &[New(4)], Stage).to_patch();
    assert!(p.windows(7).any(|w| w == b"+four\r\n"));
    let p = patch(&file(WORKTREE, b"latin1.txt"), &[New(3)], Stage).to_patch();
    assert!(p.windows(6).any(|w| w == b" caf\xe9\n"));
    let p = patch(&file(WORKTREE, b"name\xff.txt"), &[New(4)], Stage).to_patch();
    assert!(p.starts_with(b"diff --git a/name\xff.txt b/name\xff.txt\n"));
}

#[test]
fn stage_new_and_deleted_file() {
    // `git add -N` file: it is created with only the chosen lines.
    snapshot(
        "stage_new_partial",
        WORKTREE,
        b"intent.txt",
        &[New(2)],
        Stage,
    );
    // File deleted from the worktree: partial = modification, total = deletion.
    snapshot(
        "stage_deleted_partial",
        WORKTREE,
        b"new name.txt",
        &[Old(7)],
        Stage,
    );
    let f = file(WORKTREE, b"new name.txt");
    let p = patch(&f, &f.line_refs(), Stage);
    assert_eq!(p.change, Change::Deleted);
    assert_eq!(p.old_mode, Some(0o100644));
    snapshot(
        "stage_deleted_full",
        WORKTREE,
        b"new name.txt",
        &f.line_refs(),
        Stage,
    );
}

#[test]
fn stage_without_mode_change() {
    let f = file(WORKTREE, b"script.sh");
    assert_eq!((f.old_mode, f.new_mode), (Some(0o100644), Some(0o100755)));
    let p = patch(&f, &[New(2)], Stage);
    assert_eq!((p.old_mode, p.new_mode), (None, None));
    snapshot("stage_mode", WORKTREE, b"script.sh", &[New(2)], Stage);
}

// --- Unstage (index diff) ----------------------------------------------------------------

#[test]
fn unstage_near_hunks() {
    snapshot(
        "unstage_near_line_2",
        INDEX,
        b"near.txt",
        &[Old(2), New(2)],
        Unstage,
    );
    // Only the line added in the index: it leaves the index, the old one does not come back.
    snapshot(
        "unstage_near_only_added",
        INDEX,
        b"near.txt",
        &[New(16)],
        Unstage,
    );
}

#[test]
fn unstage_end_of_file_without_newline() {
    // `-no newline⏎\ No newline`, `+no newline`, `+more`: only `more` leaves the index.
    snapshot(
        "unstage_adds_newline_only_more",
        INDEX,
        b"adds-newline.txt",
        &[New(3)],
        Unstage,
    );
    // Only the old line without a newline comes back: it is not the last, it gets the newline.
    snapshot(
        "unstage_adds_newline_only_removed",
        INDEX,
        b"adds-newline.txt",
        &[Old(2)],
        Unstage,
    );
    snapshot(
        "unstage_both_without",
        INDEX,
        b"both-without.txt",
        &[Old(1), New(1)],
        Unstage,
    );
}

#[test]
fn unstage_new_deleted_renamed_file() {
    // New file in the index: partial = modification, total = removal from the index.
    snapshot("unstage_new_partial", INDEX, b"new.txt", &[New(1)], Unstage);
    let f = file(INDEX, b"new.txt");
    let p = patch(&f, &f.line_refs(), Unstage);
    assert_eq!(p.change, Change::Deleted);
    snapshot(
        "unstage_new_full",
        INDEX,
        b"new.txt",
        &f.line_refs(),
        Unstage,
    );
    // File deleted in the index: it comes back into the index with only the chosen lines.
    snapshot(
        "unstage_deleted_partial",
        INDEX,
        b"deleted.txt",
        &[Old(2)],
        Unstage,
    );
    // Rename in the index: the patch modifies the new path, without rename headers.
    let f = file(INDEX, b"new name.txt");
    assert_eq!(f.change, Change::Renamed);
    let p = patch(&f, &[Old(7), New(7)], Unstage);
    assert_eq!(p.change, Change::Modified);
    assert_eq!(p.old_path, RepoPath::from("new name.txt"));
    snapshot(
        "unstage_rename",
        INDEX,
        b"new name.txt",
        &[Old(7), New(7)],
        Unstage,
    );
}

#[test]
fn unstage_exact_bytes() {
    snapshot(
        "unstage_crlf",
        INDEX,
        b"crlf.txt",
        &[Old(3), New(3)],
        Unstage,
    );
    snapshot(
        "unstage_name_with_tab",
        INDEX,
        b"with\ttab.txt",
        &[New(4)],
        Unstage,
    );
    let p = patch(&file(INDEX, b"with\ttab.txt"), &[New(4)], Unstage).to_patch();
    assert!(p.starts_with(b"diff --git \"a/with\\ttab.txt\" \"b/with\\ttab.txt\"\n"));
}

// --- Selection ---------------------------------------------------------------------------

#[test]
fn empty_selection_no_patch() {
    let diff = parse_diff(WORKTREE).unwrap();
    for f in &diff.files {
        assert_eq!(build_patch(f, &[], Stage), Ok(None), "{}", f.path());
    }
    let f = file(INDEX, b"near.txt");
    assert_eq!(build_patch(&f, &[], Unstage), Ok(None));
}

#[test]
fn repeated_selection_counts_once() {
    let f = file(WORKTREE, b"near.txt");
    assert_eq!(
        build_patch(&f, &[New(9), New(9), Old(9)], Stage),
        build_patch(&f, &[Old(9), New(9)], Stage)
    );
}

fn selection_reason(f: &FileDiff, lines: &[LineRef], dir: PatchDirection) -> String {
    match build_patch(f, lines, dir) {
        Err(DomainError::InvalidLineSelection { path, reason }) => {
            assert_eq!(path, f.path().to_string_lossy());
            reason
        }
        other => panic!("selection error expected, got {other:?}"),
    }
}

#[test]
fn selection_of_nonexistent_lines_rejected() {
    let f = file(WORKTREE, b"near.txt");
    // Context line (3 is the same on both sides), number outside the diff, wrong side.
    let r = selection_reason(&f, &[Old(1), Old(3)], Stage);
    assert!(r.contains("removed 3"), "{r}");
    let r = selection_reason(&f, &[New(99), Old(99)], Stage);
    assert!(r.contains("removed 99, added 99"), "{r}");
    // `line 9 in the worktree` is the new line 9: there is no removed line no. 10.
    let r = selection_reason(&f, &[Old(10)], Stage);
    assert!(r.contains("removed 10"), "{r}");
    let msg = DomainError::InvalidLineSelection {
        path: "near.txt".into(),
        reason: r,
    }
    .to_string();
    assert!(msg.starts_with("invalid line selection for `near.txt`:"));
    // A mode-only change has no lines.
    let f = file(FILE, b"executable.sh");
    selection_reason(&f, &[New(1)], Stage);
}

fn unsupported(f: &FileDiff, dir: PatchDirection) -> String {
    match build_patch(f, &f.line_refs(), dir) {
        Err(DomainError::UnsupportedPatch { reason, .. }) => reason,
        other => panic!("rejection expected for {}, got {other:?}", f.path()),
    }
}

#[test]
fn unsuitable_files_rejected() {
    for path in [&b"binary-new.bin"[..], b"binary-deleted.bin", b"image.gif"] {
        let f = file(FILE, path);
        assert!(unsupported(&f, Stage).contains("binary"));
        assert!(unsupported(&f, Unstage).contains("binary"));
    }
    let f = file(SUBMODULE, b"sub");
    assert!(unsupported(&f, Stage).contains("submodule"));
    let diff = parse_diff(FILE).unwrap();
    let link = diff
        .files
        .iter()
        .find(|f| f.new_mode == Some(0o120000))
        .unwrap();
    assert!(unsupported(link, Unstage).contains("symbolic link"));
    let f = file(CONFLICT, b"conflict.txt");
    assert!(unsupported(&f, Stage).contains("conflicted"));
    // Even with an empty selection: the file does not lend itself to it.
    assert!(matches!(
        build_patch(&f, &[], Stage),
        Err(DomainError::UnsupportedPatch { .. })
    ));
    let f = file(FILE, b"renamed-modified.txt");
    assert!(unsupported(&f, Stage).contains("rename"));
    assert!(build_patch(&f, &f.line_refs(), Unstage).is_ok());
    let mut copy = f.clone();
    copy.change = Change::Copied;
    assert!(unsupported(&copy, Unstage).contains("copy"));
}

#[test]
fn line_references_in_json() {
    let refs = vec![Old(3), New(5)];
    let json = serde_json::to_string(&refs).unwrap();
    assert_eq!(json, r#"[{"old":3},{"new":5}]"#);
    assert_eq!(serde_json::from_str::<Vec<LineRef>>(&json).unwrap(), refs);
    assert_eq!(serde_json::to_string(&Unstage).unwrap(), r#""unstage""#);
    let f = file(WORKTREE, b"near.txt");
    assert_eq!(
        f.hunks[0].line_refs(),
        [
            Old(1),
            Old(2),
            New(1),
            New(2),
            Old(4),
            New(4),
            Old(9),
            New(9),
            Old(15),
            Old(16),
            New(15),
            Old(18),
            New(17)
        ]
    );
}

// --- Property tests -------------------------------------------------------------------
//
// A random diff comes from a script of lines (kept, removed, added), grouped into hunks
// with 3 context lines as git does. A small pure applier applies a patch to a
// content and checks headers, counts and context: the result is compared with the
// expected content computed from the script.

#[derive(Debug, Clone)]
struct Script {
    lines: Vec<Line>,
}

const CONTEXT: usize = 3;

fn script_strategy() -> impl Strategy<Value = Script> {
    let piece = prop_oneof![
        Just(&b"a"[..]),
        Just(&b"b"[..]),
        Just(&b"c\r"[..]),
        Just(&b"\xff"[..]),
        Just(&b""[..]),
    ];
    (
        proptest::collection::vec((0u8..4, piece), 1..30),
        any::<bool>(),
        any::<bool>(),
    )
        .prop_map(|(ops, old_nonl, new_nonl)| {
            let lines = ops
                .into_iter()
                .map(|(op, content)| Line {
                    // More kept lines than changed ones, so separate hunks form.
                    kind: match op {
                        0 => LineKind::Removed,
                        1 => LineKind::Added,
                        _ => LineKind::Context,
                    },
                    old_line: None,
                    new_line: None,
                    content: ByteText::from(content),
                    no_newline: false,
                })
                .collect();
            Script {
                lines: mark_no_newline(lines, old_nonl, new_nonl),
            }
        })
        .prop_filter("at least one changed line", |s| {
            s.lines.iter().any(|l| l.kind != LineKind::Context)
        })
}

/// Marks the last line of each side as without a newline, splitting into removed + added a
/// kept line that is so on one side only.
fn mark_no_newline(mut lines: Vec<Line>, old_nonl: bool, new_nonl: bool) -> Vec<Line> {
    let last = |lines: &[Line], skip: LineKind| lines.iter().rposition(|l| l.kind != skip);
    let split = |lines: &mut Vec<Line>, i: usize, old: bool, new: bool| {
        let mut added = lines[i].clone();
        lines[i].kind = LineKind::Removed;
        lines[i].no_newline = old;
        added.kind = LineKind::Added;
        added.no_newline = new;
        lines.insert(i + 1, added);
    };
    let old_last = last(&lines, LineKind::Added);
    let new_last = last(&lines, LineKind::Removed);
    match (old_last, new_last) {
        (Some(o), Some(n)) if o == n => {
            // Kept line, last on both sides.
            if old_nonl == new_nonl {
                lines[o].no_newline = old_nonl;
            } else {
                split(&mut lines, o, old_nonl, new_nonl);
            }
        }
        _ => {
            // The later position first, so the other does not shift.
            let mut marks: Vec<(usize, bool)> = Vec::new();
            if let Some(o) = old_last {
                marks.push((o, true));
            }
            if let Some(n) = new_last {
                marks.push((n, false));
            }
            marks.sort_by_key(|m| std::cmp::Reverse(m.0));
            for (i, old_side) in marks {
                let flag = if old_side { old_nonl } else { new_nonl };
                match (lines[i].kind, old_side) {
                    (LineKind::Context, true) => split(&mut lines, i, flag, false),
                    (LineKind::Context, false) => split(&mut lines, i, false, flag),
                    _ => lines[i].no_newline = flag,
                }
            }
        }
    }
    // An empty line without a newline does not exist: it would be zero bytes.
    for l in &mut lines {
        if l.no_newline && l.content.is_empty() {
            l.content = ByteText::from("z");
        }
    }
    canonical(lines)
}

/// First the removed and then the added in each group, like git.
fn canonical(lines: Vec<Line>) -> Vec<Line> {
    let mut out = Vec::new();
    let mut added = Vec::new();
    for l in lines {
        match l.kind {
            LineKind::Removed => out.push(l),
            LineKind::Added => added.push(l),
            LineKind::Context => {
                out.append(&mut added);
                out.push(l);
            }
        }
    }
    out.append(&mut added);
    out
}

impl Script {
    /// The lines with the numbers of the two sides.
    fn numbered(&self) -> Vec<Line> {
        let (mut old, mut new) = (1, 1);
        let mut lines = self.lines.clone();
        for l in &mut lines {
            if l.kind != LineKind::Added {
                l.old_line = Some(old);
                old += 1;
            }
            if l.kind != LineKind::Removed {
                l.new_line = Some(new);
                new += 1;
            }
        }
        lines
    }

    fn side(&self, skip: LineKind) -> Option<Vec<u8>> {
        let lines: Vec<&Line> = self.lines.iter().filter(|l| l.kind != skip).collect();
        (!lines.is_empty()).then(|| join(&lines))
    }

    fn old_side(&self) -> Option<Vec<u8>> {
        self.side(LineKind::Added)
    }

    fn new_side(&self) -> Option<Vec<u8>> {
        self.side(LineKind::Removed)
    }

    fn diff(&self) -> FileDiff {
        let lines = self.numbered();
        let changes: Vec<usize> = (0..lines.len())
            .filter(|&i| lines[i].kind != LineKind::Context)
            .collect();
        // Groups of changed lines at no more than 2 × CONTEXT lines from one another.
        let mut ranges: Vec<(usize, usize)> = Vec::new();
        for &i in &changes {
            let start = i.saturating_sub(CONTEXT);
            let end = (i + CONTEXT + 1).min(lines.len());
            match ranges.last_mut() {
                Some(r) if start <= r.1 => r.1 = end,
                _ => ranges.push((start, end)),
            }
        }
        let hunks = ranges
            .into_iter()
            .map(|(s, e)| {
                let body = lines[s..e].to_vec();
                let before = |skip| lines[..s].iter().filter(|l| l.kind != skip).count();
                let count = |skip| body.iter().filter(|l| l.kind != skip).count();
                let start = |skip| {
                    let (b, c) = (before(skip), count(skip));
                    if c == 0 { b } else { b + 1 }
                };
                Hunk {
                    old_start: start(LineKind::Added) as u32,
                    old_count: count(LineKind::Added) as u32,
                    new_start: start(LineKind::Removed) as u32,
                    new_count: count(LineKind::Removed) as u32,
                    section: ByteText::default(),
                    lines: body,
                }
            })
            .collect();
        let change = match (self.old_side(), self.new_side()) {
            (None, _) => Change::Added,
            (_, None) => Change::Deleted,
            _ => Change::Modified,
        };
        FileDiff {
            old_path: RepoPath::from("f.txt"),
            new_path: RepoPath::from("f.txt"),
            change,
            similarity: None,
            old_mode: (change != Change::Added).then_some(0o100644),
            new_mode: (change != Change::Deleted).then_some(0o100644),
            old_oid: None,
            new_oid: None,
            binary: false,
            hunks,
        }
    }

    /// The reference of each line of the script (`None` for the kept ones).
    fn refs(&self) -> Vec<Option<LineRef>> {
        self.numbered().iter().map(Line::line_ref).collect()
    }

    /// The expected lines in the result: those for which `keep` (line, selected) is true,
    /// in diff order with removed and added alternated in each group (first removed, first
    /// added, second removed...); a line without a newline that is no longer the last gets one.
    fn result(&self, keep: impl Fn(&Line, bool) -> bool, sel: &[bool]) -> Vec<Line> {
        let marked: Vec<(Line, bool)> = self
            .lines
            .iter()
            .cloned()
            .zip(sel.iter().copied())
            .collect();
        let mut out: Vec<Line> = alternate(marked)
            .into_iter()
            .filter(|(l, s)| keep(l, *s))
            .map(|(l, _)| l)
            .collect();
        let n = out.len();
        for l in out.iter_mut().take(n.saturating_sub(1)) {
            l.no_newline = false;
        }
        out
    }
}

/// Alternates removed and added in each group of changes.
fn alternate(lines: Vec<(Line, bool)>) -> Vec<(Line, bool)> {
    let mut out = Vec::new();
    let (mut removed, mut added) = (Vec::new(), Vec::new());
    let flush = |removed: &mut Vec<(Line, bool)>,
                 added: &mut Vec<(Line, bool)>,
                 out: &mut Vec<(Line, bool)>| {
        let n = removed.len().max(added.len());
        let (mut r, mut a) = (removed.drain(..), added.drain(..));
        for _ in 0..n {
            out.extend(r.next());
            out.extend(a.next());
        }
    };
    for (l, s) in lines {
        match l.kind {
            LineKind::Removed => removed.push((l, s)),
            LineKind::Added => added.push((l, s)),
            LineKind::Context => {
                flush(&mut removed, &mut added, &mut out);
                out.push((l, s));
            }
        }
    }
    flush(&mut removed, &mut added, &mut out);
    out
}

fn join(lines: &[&Line]) -> Vec<u8> {
    let mut out = Vec::new();
    for l in lines {
        out.extend_from_slice(l.content.as_bytes());
        if !l.no_newline {
            out.push(b'\n');
        }
    }
    out
}

/// Lines of a content, each with its newline (the last may lack it).
fn split_lines(content: &[u8]) -> Vec<&[u8]> {
    content.split_inclusive(|&b| b == b'\n').collect()
}

/// Adds a line to the result: after a line without a newline no other can follow.
fn push(out: &mut Vec<u8>, line: &[u8]) -> Result<(), String> {
    if out.last().is_some_and(|&b| b != b'\n') {
        return Err("line without a newline followed by another line".into());
    }
    out.extend_from_slice(line);
    Ok(())
}

/// Applies `patch` to `base` (`None` = absent file) like `git apply` without `--recount`:
/// checks headers, counts, line numbers and context. `None` in the result = deleted
/// file.
fn apply(base: Option<&[u8]>, patch: &FileDiff) -> Result<Option<Vec<u8>>, String> {
    let base = match (base, patch.change) {
        (Some(_), Change::Added) => return Err("new file, but it already exists".into()),
        (None, Change::Added) => Vec::new(),
        (None, _) => return Err("the file does not exist".into()),
        (Some(b), _) => b.to_vec(),
    };
    let src = split_lines(&base);
    let mut out: Vec<u8> = Vec::new();
    let mut out_lines = 0usize;
    let mut pos = 0usize;
    for h in &patch.hunks {
        let first = if h.old_count == 0 {
            h.old_start as usize
        } else {
            (h.old_start as usize).checked_sub(1).ok_or("old_start 0")?
        };
        if first < pos || first > src.len() {
            return Err(format!("hunk out of place: {first} (cursor {pos})"));
        }
        for l in &src[pos..first] {
            push(&mut out, l)?;
            out_lines += 1;
        }
        pos = first;
        let expected_new = if h.new_count == 0 {
            out_lines
        } else {
            out_lines + 1
        };
        if h.new_start as usize != expected_new {
            return Err(format!(
                "new_start {} instead of {expected_new}",
                h.new_start
            ));
        }
        let (mut old_n, mut new_n) = (0, 0);
        for l in &h.lines {
            let mut bytes = l.content.as_bytes().to_vec();
            if !l.no_newline {
                bytes.push(b'\n');
            }
            if l.kind != LineKind::Added {
                if src.get(pos) != Some(&&bytes[..]) {
                    return Err(format!("different context at line {}", pos + 1));
                }
                if l.old_line != Some(pos as u32 + 1) {
                    return Err("wrong old line number".into());
                }
                pos += 1;
                old_n += 1;
            }
            if l.kind != LineKind::Removed {
                push(&mut out, &bytes)?;
                out_lines += 1;
                new_n += 1;
                if l.new_line != Some(out_lines as u32) {
                    return Err("wrong new line number".into());
                }
            }
        }
        if (old_n, new_n) != (h.old_count, h.new_count) {
            return Err(format!(
                "counts {}/{} instead of {old_n}/{new_n}",
                h.old_count, h.new_count
            ));
        }
    }
    for l in &src[pos..] {
        push(&mut out, l)?;
    }
    if patch.change == Change::Deleted {
        if !out.is_empty() {
            return Err("deletion that leaves content".into());
        }
        return Ok(None);
    }
    Ok(Some(out))
}

/// Applies the built patch, or leaves `base` if there is no patch.
fn applied(
    base: Option<Vec<u8>>,
    f: &FileDiff,
    refs: &[LineRef],
    dir: PatchDirection,
) -> Result<Option<Vec<u8>>, String> {
    match build_patch(f, refs, dir).map_err(|e| e.to_string())? {
        None => Ok(base),
        Some(p) => {
            let bytes = p.to_patch();
            let reread = parse_diff(&bytes).map_err(|e| e.to_string())?;
            if reread.files != [p.clone()] {
                return Err("the patch is not read back identical".into());
            }
            apply(base.as_deref(), &p)
        }
    }
}

fn chosen(script: &Script, sel: &[bool]) -> Vec<LineRef> {
    script
        .refs()
        .iter()
        .zip(sel)
        .filter_map(|(r, s)| r.filter(|_| *s))
        .collect()
}

fn bytes_of(lines: &[Line], absent: bool) -> Option<Vec<u8>> {
    if absent {
        return None;
    }
    let refs: Vec<&Line> = lines.iter().collect();
    Some(join(&refs))
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(512))]

    /// The script itself is consistent: the generated diff leads from the old to the new.
    #[test]
    fn the_generator_produces_valid_diffs(script in script_strategy()) {
        let f = script.diff();
        prop_assert_eq!(apply(script.old_side().as_deref(), &f), Ok(script.new_side()));
    }

    /// Stage: the selected lines enter, the others do not; full selection = original diff;
    /// empty selection = no patch.
    #[test]
    fn stage_applies_only_the_chosen_lines(
        script in script_strategy(),
        bits in proptest::collection::vec(any::<bool>(), 64),
    ) {
        let f = script.diff();
        let sel: Vec<bool> = (0..script.lines.len()).map(|i| bits[i % 64]).collect();
        let refs = chosen(&script, &sel);
        let target = script.result(
            |l, s| match l.kind {
                LineKind::Context => true,
                LineKind::Removed => !s,
                LineKind::Added => s,
            },
            &sel,
        );
        let all_removed = f.change == Change::Deleted && target.is_empty();
        let expected = if refs.is_empty() {
            script.old_side()
        } else {
            bytes_of(&target, all_removed)
        };
        prop_assert_eq!(applied(script.old_side(), &f, &refs, Stage), Ok(expected));
        prop_assert_eq!(build_patch(&f, &[], Stage), Ok(None));

        let all = f.line_refs();
        let total = build_patch(&f, &all, Stage).unwrap().unwrap();
        prop_assert_eq!(&total.hunks, &f.hunks);
        prop_assert_eq!(total.change, f.change);
    }

    /// Unstage: the selected lines leave the index, the others stay; gives the same
    /// content as staging the unselected lines starting from the old side.
    #[test]
    fn unstage_removes_only_the_chosen_lines(
        script in script_strategy(),
        bits in proptest::collection::vec(any::<bool>(), 64),
    ) {
        let f = script.diff();
        let sel: Vec<bool> = (0..script.lines.len()).map(|i| bits[i % 64]).collect();
        let refs = chosen(&script, &sel);
        let target = script.result(
            |l, s| match l.kind {
                LineKind::Context => true,
                LineKind::Removed => s,
                LineKind::Added => !s,
            },
            &sel,
        );
        let all_removed = f.change == Change::Added && target.is_empty();
        let expected = if refs.is_empty() {
            script.new_side()
        } else {
            bytes_of(&target, all_removed)
        };
        let unstaged = applied(script.new_side(), &f, &refs, Unstage);
        prop_assert_eq!(&unstaged, &Ok(expected));

    // The same content as staging the complement (if the complement is not empty).
        let others: Vec<LineRef> = f.line_refs().into_iter().filter(|r| !refs.contains(r)).collect();
        if !others.is_empty() && !refs.is_empty() {
            prop_assert_eq!(&applied(script.old_side(), &f, &others, Stage), &unstaged);
        }
    // Full unstage: back to the old side.
        prop_assert_eq!(applied(script.new_side(), &f, &f.line_refs(), Unstage), Ok(script.old_side()));
    }

    /// Stage and then unstage of the same selection (in the index diff, which after staging is
    /// the patch itself) bring back the initial content.
    #[test]
    fn stage_then_unstage_returns_to_the_start(
        script in script_strategy(),
        bits in proptest::collection::vec(any::<bool>(), 64),
    ) {
        let f = script.diff();
        let sel: Vec<bool> = (0..script.lines.len()).map(|i| bits[i % 64]).collect();
        let refs = chosen(&script, &sel);
        if refs.is_empty() {
            return Ok(());
        }
        let staged = build_patch(&f, &refs, Stage).unwrap().unwrap();
        let index = apply(script.old_side().as_deref(), &staged).unwrap();
        let back = applied(index, &staged, &staged.line_refs(), Unstage);
        prop_assert_eq!(back, Ok(script.old_side()));
    }
}
